    def handle_data(self, data):
        if self.in_td or self.in_th:
            self.current_row.append(data.strip())

parser = TableParser()
parser.feed(content)

# Find all functions and their Total values
# The structure is: function name, then Outlays, etc., then Total for each function
# FY1981: Oct (1980) through Sept (1981) = indices 1-12

header = parser.rows[0]
print("Header columns (14 total):", header)

# Parse rows to extract function totals
functions_data = []
current_function = None
for row in parser.rows[1:]:
    if not row or len(row) < 2:
        continue

    first = row[0].strip()

    # Check if this is a function name (bolded in the table)
    if first and first not in ['Outlays', 'Proprietary receipts from the public', 
                               'Intrabudgetary transactions', 'Total']:
        current_function = first
    # Check if this is a Total row
    elif first == 'Total' and current_function:
        # Extract monthly values for columns 1-12 (Oct through Sept of FY1981)
        # Note: columns 13-15 are Oct (FY82), Cumulative, Comparable period
        values = []
        for i in range(1, 13):
            if i < len(row):
                val_str = row[i].strip().replace(',', '').replace('-', '0').replace('*', '0')
                if val_str == '' or val_str == '-':
                    val_str = '0'
                try:
                    values.append(int(val_str.replace('$', '')))
                except ValueError:
                    values.append(0)
            else:
                values.append(0)
        functions_data.append((current_function, values))
        current_function = None  # Reset to avoid duplicate

print(f"\nFound {len(functions_data)} functions with totals for FY1981")
for func, vals in functions_data:
    print(f"{func}: {vals}")
